/**
 * Track: a song in the catalog — uploaded by a creator, added by staff, or
 * generated by AI (PRD §13 `tracks`).
 */
import mongoose from "mongoose";
import { TRACK_ADDED_VIA, TRACK_SOURCE, TRACK_STATUS } from "../config/constants.js";

const audioFormatSchema = new mongoose.Schema(
  {
    bitrateKbps: { type: Number, required: true }, // e.g. 128, 320
    codec: { type: String, required: true }, // e.g. "mp3", "aac"
    url: { type: String, required: true },
  },
  { _id: false }
);

const trackSchema = new mongoose.Schema(
  {
    title: { type: String, required: true, trim: true, maxlength: 150 },
    artistId: { type: mongoose.Schema.Types.ObjectId, ref: "ArtistProfile", required: true },
    albumId: { type: mongoose.Schema.Types.ObjectId, ref: "Album", default: null },
    uploadedBy: { type: mongoose.Schema.Types.ObjectId, ref: "User", required: true },

    audio: {
      url: { type: String, default: null }, // original upload; set once the upload completes
      formats: { type: [audioFormatSchema], default: [] }, // transcoded versions
      durationSec: { type: Number, default: 0, min: 0 },
    },
    coverUrl: { type: String, default: null },

    genres: { type: [String], default: [] },
    vibes: { type: [String], default: [] },
    mood: { type: String, trim: true, default: null },
    bpm: { type: Number, min: 20, max: 300, default: null },
    energy: { type: Number, min: 0, max: 1, default: null },
    language: { type: String, trim: true, default: null },
    explicit: { type: Boolean, default: false },
    lyrics: { type: String, default: "" },

    source: { type: String, enum: TRACK_SOURCE, default: "upload" },
    addedVia: { type: String, enum: TRACK_ADDED_VIA, default: "creator" },
    status: { type: String, enum: TRACK_STATUS, default: "processing" },
    scheduledAt: { type: Date, default: null },
    featured: { type: Boolean, default: false },

    playCount: { type: Number, default: 0, min: 0 },
    likeCount: { type: Number, default: 0, min: 0 },
  },
  { timestamps: true }
);

// Indexes from PRD §13 "Important indexes"
trackSchema.index({ genres: 1 });
trackSchema.index({ vibes: 1 });
trackSchema.index({ status: 1 });
trackSchema.index({ status: 1, scheduledAt: 1 });
trackSchema.index({ artistId: 1, createdAt: -1 });

export const Track = mongoose.model("Track", trackSchema);
